#!/usr/bin/env node
'use strict';
// Crownicles WhatsApp: MQTT V4, self-contained isolated Termux broker test.
// No game Core, MariaDB, Baileys or WhatsApp is initialized.
const fs=require('node:fs'),os=require('node:os'),path=require('node:path'),zlib=require('node:zlib'),crypto=require('node:crypto');
const payload=JSON.parse(zlib.inflateSync(Buffer.from('','base64')).toString('utf8'));
const tmp=fs.mkdtempSync(path.join(os.tmpdir(),'cw-mqtt-standalone-v4-'));
process.once('exit',()=>{try{fs.rmSync(tmp,{recursive:true,force:true})}catch{}});
for(const [relative,entry] of Object.entries(payload)){
 if(!/^(?:src|tools)\/[a-z0-9-]+\.cjs$/i.test(relative))throw Error('BUNDLE_INVALID_PATH');
 const data=Buffer.from(entry.source,'utf8');
 if(crypto.createHash('sha256').update(data).digest('hex')!==entry.sha256)throw Error('BUNDLE_HASH_MISMATCH');
 const out=path.join(tmp,relative);fs.mkdirSync(path.dirname(out),{recursive:true,mode:0o700});fs.writeFileSync(out,data,{mode:0o600});
}
require(path.join(tmp,'tools/mqtt-real-isolated-v4.cjs'));
